export const meta = {
  name: 'alpha-beta',
  description: 'Two parallel agents returning the words alpha and beta',
  phases: [
    { title: 'Emit', detail: 'two agents in parallel' },
  ],
}

phase('Emit')
const results = await parallel([
  () => agent("Return exactly the word: alpha\n\nYour entire final response must be that one word, lowercase, with no punctuation, explanation, or tool use.", {label: 'alpha'}),
  () => agent("Return exactly the word: beta\n\nYour entire final response must be that one word, lowercase, with no punctuation, explanation, or tool use.", {label: 'beta'}),
])
return { first: results[0], second: results[1] }

